.ds-website-button{display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 28px;
  min-height: 56px;
  padding: 16px 24px;
  border-radius: 12px;
  background: #102d44;
  color: white;
  text-decoration: none;
  font-weight: 600;
  border: 1px solid transparent;
  transition:
    background 0.2s,
    transform 0.2s;}.ds-website-button:hover{background: #285c86;
  transform: translateY(-2px);}.ds-website-button{font-family:Figtree,Arial,sans-serif;}.ds-website-button:focus-visible,.ds-website-text-link:focus-visible{outline:3px solid #285c86;outline-offset:6px}@media(prefers-reduced-motion:reduce){.ds-website-button{transition-duration:.01ms}}

.ds-website-button{display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 28px;
  min-height: 56px;
  padding: 16px 24px;
  border-radius: 12px;
  background: #102d44;
  color: white;
  text-decoration: none;
  font-weight: 600;
  border: 1px solid transparent;
  transition:
    background 0.2s,
    transform 0.2s;}.ds-website-button:hover{background: #285c86;
  transform: translateY(-2px);}.ds-website-button{font-family:Figtree,Arial,sans-serif;}.ds-website-button:focus-visible,.ds-website-text-link:focus-visible{outline:3px solid #285c86;outline-offset:6px}@media(prefers-reduced-motion:reduce){.ds-website-button{transition-duration:.01ms}}.ds-website-button-small{font-size: 14px;
  min-height: 46px;
  padding: 10px 18px;
  gap: 20px;}

.ds-website-text-link{display: inline-flex;
  align-items: center;
  gap: 16px;
  color: #285c86;
  font-weight: 600;
  min-height: 48px;}.ds-website-text-link{font-family:Figtree,Arial,sans-serif;text-underline-offset:5px}.ds-website-button:focus-visible,.ds-website-text-link:focus-visible{outline:3px solid #285c86;outline-offset:6px}

.ds-website-errand-slip{position: absolute;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 17px 20px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 16px 38px -20px #102d4450;
  font-size: 14px;
  line-height: 1.3;
  z-index: 4;
  width: 250px;}.ds-website-errand-slip small{font-size: 10px;
  display: block;
  color: #526779;
  margin-top: 5px;}.ds-website-slip-number{width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  background: #e5f0f9;
  color: #285c86;
  font-size: 12px;
  border-radius: 50%;
  flex-shrink: 0;}.ds-website-errand-slip{position:relative;color:#102d44;font-family:Figtree,Arial,sans-serif;}

.ds-website-steps{list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 28px;}.ds-website-steps li{background: #fbfbf8;
  display: grid;
  grid-template-columns: 80px 1fr 180px;
  align-items: center;
  gap: 40px;
  padding: 64px;
  min-height: 340px;
  border-radius: 16px;
  position: relative;
  transform-origin: 50% 0;}.ds-website-step-number{font-size: 52px;
  align-self: start;
  font-weight: 450;
  letter-spacing: -0.04em;}.ds-website-steps h3{font-size: clamp(30px, 3.5vw, 48px);
  font-weight: 550;
  max-width: 540px;}.ds-website-steps p{max-width: 420px;
  font-size: 16px;
  margin-top: 20px;}.ds-website-step-art{width: 160px;
  height: 160px;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;}.ds-website-steps{color:#102d44;font-family:Figtree,Arial,sans-serif;}.ds-website-steps h3{margin:0;line-height:1.06;letter-spacing:-.035em}.ds-website-steps p{margin:20px 0 0;line-height:1.65}@media(max-width:700px){.ds-website-steps li{grid-template-columns:40px 1fr;gap:16px;padding:30px 24px;min-height:300px}.ds-website-step-art{grid-column:2;width:80px;height:80px;justify-self:end}.ds-website-steps h3{font-size:32px}.ds-website-steps p{font-size:15px}.ds-website-step-number{font-size:30px}}

.ds-website-phone{height: 100%;
  background: #fbfbf8;
  border: 8px solid #102d44;
  border-radius: 40px;
  box-shadow: 16px 30px 45px -24px #102d4450;
  overflow: hidden;}.ds-website-phone-top{height: 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  font-size: 9px;
  font-weight: 650;
  position: relative;}.ds-website-phone-camera{width: 65px;
  height: 17px;
  border-radius: 12px;
  background: #102d44;
  position: absolute;
  left: 50%;
  top: 5px;
  transform: translateX(-50%);}.ds-website-phone-body{padding: 22px 16px 0;}.ds-website-phone-greeting{font-size: 11px;
  color: #526779;
  margin-bottom: 5px;}.ds-website-phone h2{font-size: 28px;
  letter-spacing: -0.025em;}.ds-website-phone-preview{margin:0;width:310px;color:#102d44;font-family:Figtree,Arial,sans-serif;}.ds-website-phone{height:540px;box-sizing:border-box}.ds-website-phone h2{margin:0;line-height:1.06}.ds-website-phone-greeting{margin-top:0}.ds-website-phone-preview figcaption{margin-top:20px;text-align:center;font-size:10px;color:#526779}
